/**
 * Cut a release: verify the themes still generate, bump the version, close the
 * CHANGELOG's Unreleased section, then commit and tag.
 *
 * Because themes/ is gitignored, a release commit contains no theme JSON at all
 * — the VSIX is regenerated by vscode:prepublish. So the only gate that matters
 * here is that src/quasar.yaml still builds; that runs before anything is
 * written, so a broken YAML aborts with the tree untouched.
 *
 *   npm run release -- patch|minor|major|x.y.z [--dry-run] [--allow-empty]
 *
 * Nothing is pushed. The tag and commit stay local until you push them.
 */
const fs = require("fs");
const path = require("path");
const { execFileSync } = require("child_process");
const build = require("./build");

const ROOT = path.join(__dirname, "..");
const RELEASE_BRANCH = "master";
const UNRELEASED = "## [Unreleased]";

const git = (...args) =>
  execFileSync("git", args, { cwd: ROOT, encoding: "utf-8" }).trim();

const fail = (message) => {
  throw new Error(message);
};

const readJson = (file) =>
  JSON.parse(fs.readFileSync(path.join(ROOT, file), "utf-8"));

/** Write JSON back in npm's own formatting: 2-space indent, trailing newline. */
const writeJson = (file, value) =>
  fs.writeFileSync(
    path.join(ROOT, file),
    JSON.stringify(value, null, 2) + "\n",
  );

/** "patch"/"minor"/"major" relative to `from`, or an explicit x.y.z. */
function nextVersion(from, bump) {
  if (/^\d+\.\d+\.\d+$/.test(bump)) return bump;

  const [major, minor, patch] = from.split(".").map(Number);
  switch (bump) {
    case "major":
      return `${major + 1}.0.0`;
    case "minor":
      return `${major}.${minor + 1}.0`;
    case "patch":
      return `${major}.${minor}.${patch + 1}`;
    default:
      return fail(`Unknown bump "${bump}" — use patch, minor, major or x.y.z`);
  }
}

/**
 * Retitle the Unreleased section as the new version and open an empty one above
 * it, Keep-a-Changelog style. Returns the rewritten file, or null if there was
 * nothing under Unreleased to release.
 */
function rollChangelog(text, version, date, allowEmpty) {
  const at = text.indexOf(UNRELEASED);
  if (at === -1) fail(`No "${UNRELEASED}" heading in CHANGELOG.md`);

  const body = text.slice(at + UNRELEASED.length).split(/^## /m)[0];
  if (!body.trim() && !allowEmpty) return null;

  return (
    text.slice(0, at) +
    `${UNRELEASED}\n\n## [${version}] - ${date}` +
    text.slice(at + UNRELEASED.length)
  );
}

module.exports = async ([bump, ...flags] = []) => {
  const dry = flags.includes("--dry-run");
  const allowEmpty = flags.includes("--allow-empty");

  if (!bump) fail("Usage: npm run release -- patch|minor|major|x.y.z [--dry-run]");

  // Pre-flight: a release must be reproducible from a clean, known checkout.
  const branch = git("rev-parse", "--abbrev-ref", "HEAD");
  if (branch !== RELEASE_BRANCH) {
    fail(`On branch "${branch}" — releases are cut from "${RELEASE_BRANCH}"`);
  }
  if (git("status", "--porcelain", "--untracked-files=no")) {
    fail("Working tree has uncommitted changes — commit or stash them first");
  }

  const pkg = readJson("package.json");
  const version = nextVersion(pkg.version, bump);
  const tag = `v${version}`;

  if (git("tag", "--list", tag)) fail(`Tag ${tag} already exists`);

  const changelogPath = path.join(ROOT, "CHANGELOG.md");
  const changelog = rollChangelog(
    fs.readFileSync(changelogPath, "utf-8"),
    version,
    new Date().toISOString().slice(0, 10),
    allowEmpty,
  );
  if (!changelog) {
    fail(
      `Nothing under "${UNRELEASED}" in CHANGELOG.md — describe the release, ` +
        "or pass --allow-empty",
    );
  }

  // The gate: themes must generate, and what lands in themes/ must round-trip.
  // verify.js is a self-executing script that exits the process, so it runs as a
  // child rather than a require; a non-zero exit throws out of here.
  await build();
  execFileSync(process.execPath, [path.join(__dirname, "verify.js")], {
    cwd: ROOT,
    stdio: "inherit",
  });

  console.log(`${pkg.version} -> ${version}`);

  if (dry) {
    console.log(`would commit package.json, package-lock.json, CHANGELOG.md`);
    console.log(`would tag ${tag}`);
    return;
  }

  writeJson("package.json", { ...pkg, version });

  // The lockfile carries the version twice: at the root and in its own entry.
  const lock = readJson("package-lock.json");
  lock.version = version;
  if (lock.packages && lock.packages[""]) lock.packages[""].version = version;
  writeJson("package-lock.json", lock);

  fs.writeFileSync(changelogPath, changelog);

  git("add", "--", "package.json", "package-lock.json", "CHANGELOG.md");
  git("commit", "-m", `Release ${tag}`);
  git("tag", "-a", tag, "-m", tag);

  console.log(`committed and tagged ${tag}`);
  console.log(`next: git push --follow-tags && npm run publish`);
};

if (require.main === module) {
  module.exports(process.argv.slice(2)).catch((error) => {
    console.error(error.message);
    process.exit(1);
  });
}
